const fs = require('fs');
const path = require('path');
const gen = require('../backend/topology-sql');

const outputPath = path.join(__dirname, '..', 'backend', 'world-seed.sql');

const header = [
  'DELETE FROM attack_contributions;',
  'DELETE FROM attack_targets;',
  'DELETE FROM territory_neighbors;',
  'DELETE FROM territories;',
  '',
  '-- Default Three Frontiers topology (see map-registry.js). The rows below are',
  '-- generated by backend/topology-sql.js -- never hand-edit them here. To regenerate after',
  '-- changing the default map, run: node scripts/generate-world-seed.js',
  '-- Structure: capital -> home ring (3) -> frontier ring (3), identical and rotated 120',
  '-- degrees for blue/red/green, plus 3 contested border zones (one per faction pair) and a',
  '-- shared central core equidistant from all three capitals. This file intentionally never',
  '-- removes player accounts, their buildings, or progress: world seeding must never be able',
  '-- to wipe them out.',
  '',
].join('\n');

const body = `${gen.buildTerritoryValuesSQL()}\n\n${gen.buildNeighborValuesSQL()}\n`;

fs.writeFileSync(outputPath, `${header}\n${body}`);
console.log('wrote', fs.statSync(outputPath).size, 'bytes');
